package com.mygo.music;

import android.app.*;
import android.widget.*;
import org.json.*;
import java.util.*;

/** Playlist mutations use the same source exports as the original desktop host. */
final class SourcePlaylists {
    interface Listener {void error(String message);void play(PluginManager.PluginInfo source,String title,JSONObject track);String currentId(String source);}
    private final Activity activity;private final PluginManager manager;private final Listener listener;
    SourcePlaylists(Activity activity,PluginManager manager,Listener listener){this.activity=activity;this.manager=manager;this.listener=listener;}
    private boolean alive(){return !activity.isFinishing()&&!activity.isDestroyed();}
    private interface Answer {void value(String raw)throws Exception;}
    private void call(PluginManager.PluginInfo source,String method,JSONObject args,Answer answer){manager.export(source.id,method,args,(ok,raw)->{if(!alive())return;if(!ok){listener.error(raw);return;}try{answer.value(raw);}catch(Exception error){listener.error("歌单结果格式无效："+error.getMessage());}});}
    private JSONObject args(String id){try{return new JSONObject().put("id",id);}catch(Exception error){throw new IllegalArgumentException(error);}}
    void show(PluginManager.PluginInfo source){call(source,"playlists",new JSONObject(),raw->{JSONArray lists=new JSONArray(raw);ArrayList<JSONObject> items=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();for(int i=0;i<lists.length();i++){JSONObject item=lists.optJSONObject(i);if(item!=null&&!item.optString("id").isEmpty()){items.add(item);labels.add(item.optString("name","歌单")+(item.optBoolean("mine")?" · 我的":""));}}if(items.isEmpty())labels.add("暂无歌单");ListView view=new ListView(activity);view.setAdapter(new ArrayAdapter<String>(activity,android.R.layout.simple_list_item_1,labels));AlertDialog.Builder builder=new AlertDialog.Builder(activity).setTitle(source.name+" · 歌单").setView(view).setNegativeButton("关闭",null);if(source.supports("createPlaylist"))builder.setPositiveButton("新建歌单",null);AlertDialog dialog=builder.create();view.setOnItemClickListener((parent,row,index,id)->{if(index<items.size()){dialog.dismiss();open(source,items.get(index));}});view.setOnItemLongClickListener((parent,row,index,id)->{if(index<items.size())manage(source,items.get(index),()->{dialog.dismiss();show(source);});return true;});dialog.setOnShowListener(value->{if(source.supports("createPlaylist"))dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(view1->namePrompt("新建歌单","",name->{JSONObject params=new JSONObject().put("name",name);call(source,"createPlaylist",params,result->{dialog.dismiss();show(source);});}));});dialog.show();});}
    void addTrack(PluginManager.PluginInfo source,String trackId){call(source,"playlists",new JSONObject(),raw->{JSONArray result=new JSONArray(raw);ArrayList<JSONObject> items=new ArrayList<>();ArrayList<String> names=new ArrayList<>();for(int i=0;i<result.length();i++){JSONObject item=result.optJSONObject(i);if(item!=null&&editable(item)){items.add(item);names.add(item.optString("name","歌单"));}}if(items.isEmpty()){listener.error("没有可编辑的来源歌单，请先新建歌单");return;}new AlertDialog.Builder(activity).setTitle("选择来源歌单").setItems(names.toArray(new String[0]),(dialog,index)->{try{call(source,"addToPlaylist",args(items.get(index).getString("id")).put("trackIds",new JSONArray().put(trackId)),value->Toast.makeText(activity,"已加入来源歌单",Toast.LENGTH_SHORT).show());}catch(Exception error){listener.error(error.getMessage());}}).setNegativeButton("取消",null).show();});}
    void open(PluginManager.PluginInfo source,JSONObject summary){call(source,"playlist",args(summary.optString("id")),raw->{JSONObject playlist=new JSONObject(raw);for(String key:new String[]{"id","name","mine","fixed","saved"})if(!playlist.has(key)&&summary.has(key))playlist.put(key,summary.get(key));JSONArray tracks=playlist.optJSONArray("tracks");if(tracks==null)throw new JSONException("缺少歌曲列表");ArrayList<JSONObject> items=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();for(int i=0;i<tracks.length();i++){JSONObject track=tracks.optJSONObject(i);if(track==null||track.optString("id").isEmpty())throw new JSONException("歌曲缺少标识");items.add(track);labels.add(trackLabel(track));}if(items.isEmpty())labels.add("歌单暂无歌曲");ListView list=new ListView(activity);list.setAdapter(new ArrayAdapter<String>(activity,android.R.layout.simple_list_item_1,labels));AlertDialog dialog=new AlertDialog.Builder(activity).setTitle(playlist.optString("name","歌单")+" · "+items.size()+" 首").setView(list).setPositiveButton("歌单操作",null).setNegativeButton("关闭",null).create();list.setOnItemClickListener((parent,row,index,id)->{if(index<items.size()){dialog.dismiss();listener.play(source,playlist.optString("name","歌单"),items.get(index));}});list.setOnItemLongClickListener((parent,row,index,id)->{if(index<items.size())trackActions(source,playlist,items,index,()->{dialog.dismiss();open(source,playlist);});return true;});dialog.setOnShowListener(value->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(view->manage(source,playlist,()->{dialog.dismiss();show(source);})));dialog.show();});}
    private String trackLabel(JSONObject track){String title=track.optString("name",track.optString("title","歌曲"));JSONArray artists=track.optJSONArray("artists");if(artists!=null&&artists.length()>0&&artists.optJSONObject(0)!=null)title+=" · "+artists.optJSONObject(0).optString("name");return title;}
    private boolean editable(JSONObject playlist){return playlist.optBoolean("mine")&&!playlist.optBoolean("fixed");}
    private void manage(PluginManager.PluginInfo source,JSONObject playlist,Runnable reload){ArrayList<String> labels=new ArrayList<>(),methods=new ArrayList<>();boolean editable=editable(playlist);if(editable&&source.supports("addToPlaylist")){labels.add("加入当前歌曲");methods.add("addToPlaylist");}if(editable&&source.supports("renamePlaylist")){labels.add("重命名歌单");methods.add("renamePlaylist");}if(editable&&source.supports("deletePlaylist")){labels.add("删除歌单");methods.add("deletePlaylist");}if(!playlist.optBoolean("mine")&&source.supports("savePlaylist")){labels.add(playlist.optBoolean("saved")?"取消收藏歌单":"收藏歌单");methods.add("savePlaylist");}if(labels.isEmpty()){listener.error("此歌单没有可用的管理操作");return;}new AlertDialog.Builder(activity).setTitle(playlist.optString("name","歌单操作")).setItems(labels.toArray(new String[0]),(dialog,index)->{String method=methods.get(index),id=playlist.optString("id");try{if(method.equals("renamePlaylist")){namePrompt("重命名歌单",playlist.optString("name"),name->call(source,method,args(id).put("name",name),raw->reload.run()));}else if(method.equals("deletePlaylist")){new AlertDialog.Builder(activity).setTitle("删除歌单").setMessage("确定删除 "+playlist.optString("name","此歌单")+"？").setNegativeButton("取消",null).setPositiveButton("删除",(confirmation,which)->call(source,method,args(id),raw->reload.run())).show();}else if(method.equals("savePlaylist")){call(source,method,args(id).put("on",!playlist.optBoolean("saved")),raw->reload.run());}else{String track=listener.currentId(source.id);if(track.isEmpty()){listener.error("请先播放这个音乐源的一首歌曲");return;}call(source,method,args(id).put("trackIds",new JSONArray().put(track)),raw->reload.run());}}catch(Exception error){listener.error(error.getMessage());}}).setNegativeButton("关闭",null).show();}
    private void trackActions(PluginManager.PluginInfo source,JSONObject playlist,ArrayList<JSONObject> tracks,int index,Runnable reload){JSONObject track=tracks.get(index);ArrayList<String> labels=new ArrayList<>(),methods=new ArrayList<>();labels.add("播放歌曲");methods.add("play");if(editable(playlist)&&source.supports("removeFromPlaylist")){labels.add("从歌单移除");methods.add("removeFromPlaylist");}if(editable(playlist)&&source.supports("movePlaylistTrack")){if(index>0){labels.add("上移一首");methods.add("up");}if(index<tracks.size()-1){labels.add("下移一首");methods.add("down");}}new AlertDialog.Builder(activity).setTitle(trackLabel(track)).setItems(labels.toArray(new String[0]),(dialog,which)->{String method=methods.get(which);try{if(method.equals("play")){listener.play(source,playlist.optString("name","歌单"),track);return;}JSONObject params=args(playlist.optString("id"));if(method.equals("removeFromPlaylist")){new AlertDialog.Builder(activity).setTitle("从歌单移除").setMessage(trackLabel(track)).setNegativeButton("取消",null).setPositiveButton("移除",(confirm,value)->{try{call(source,method,params.put("trackIds",new JSONArray().put(track.getString("id"))),raw->reload.run());}catch(Exception error){listener.error(error.getMessage());}}).show();}else call(source,"movePlaylistTrack",params.put("from",index).put("to",method.equals("up")?index-1:index+1),raw->reload.run());}catch(Exception error){listener.error(error.getMessage());}}).setNegativeButton("关闭",null).show();}
    private interface NameAction {void run(String name)throws Exception;}
    private void namePrompt(String title,String current,NameAction action){EditText input=new EditText(activity);input.setSingleLine(true);input.setText(current);input.setHint("歌单名称");AlertDialog dialog=new AlertDialog.Builder(activity).setTitle(title).setView(input).setPositiveButton("保存",null).setNegativeButton("取消",null).create();dialog.setOnShowListener(value->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(view->{String name=input.getText().toString().trim();if(name.isEmpty()){input.setError("请输入歌单名称");return;}if(name.length()>256){input.setError("歌单名称过长");return;}try{action.run(name);dialog.dismiss();}catch(Exception error){listener.error(error.getMessage());}}));dialog.show();}
}
